module.exports = async function() {
  // Rotating topic pool, ~3–4 per category.
  // To switch to a Directus-managed list later, replace this step with an
  // item-read on a `planned_topics` collection (filtered by status=queued,
  // sorted by priority) and emit the first row's `topic` field.
  const TOPICS = [
    // ── ahorro ──────────────────────────────────────────────
    'Cómo armar tu fondo de emergencia sin sufrir (paso a paso para mexicanos en sus 20s)',
    'CETES Directo vs. cuenta de ahorro tradicional: dónde meter los primeros 50 mil pesos',
    'El método de los sobres digitales: cómo aplicarlo en CoDi o con apps mexicanas',
    'Ahorro automático: por qué dejarlo en manos del bot vence al "voy a ser disciplinado"',

    // ── creditos ────────────────────────────────────────────
    'Buró de Crédito explicado sin paranoia: qué ven los bancos cuando piden tu reporte',
    'Cómo subir tu score en 6 meses sin pagar agencias "reparadoras" que son un fraude',
    'Tarjeta de crédito como herramienta de ahorro: meses sin intereses bien usados',
    'CAT vs. tasa de interés: el número que de verdad importa al comparar créditos',

    // ── afore ──────────────────────────────────────────────
    'Cómo escoger AFORE en 2026: rendimientos netos vs. comisiones, sin marketing',
    'Aportaciones voluntarias a tu AFORE: la deducción fiscal que nadie te explicó',
    'Cambio de AFORE: cuándo conviene y cuándo es puro ruido',
    'Modalidad 40 del IMSS: el truco para boost a tu pensión que pocos conocen',

    // ── ppr ────────────────────────────────────────────────
    'PPR vs. Plan Personal de Retiro vs. fondo indexado: qué es cada uno y cuál te toca',
    'Deducción del 152: cuánto te puedes deducir en realidad y cómo reclamarlo en abril'
  ];

  // Pick by day-of-year so the topic is deterministic per date and cycles
  // through the full list before repeating (~14 days, then loops).
  const now = new Date();
  const start = new Date(now.getFullYear(), 0, 0);
  const diffMs = now - start;
  const dayOfYear = Math.floor(diffMs / 86400000);

  const topic = TOPICS[dayOfYear % TOPICS.length];
  const date  = now.toISOString().slice(0, 10); // YYYY-MM-DD

  return { topic, date };
};

module.exports = async function(data) {
  // Directus request operation puts the parsed JSON under `.data`.
  const res = data.generate_article && data.generate_article.data;
  if (!res || !res.ok || !res.article) {
    const err = res && res.error ? res.error : 'unknown error from /api/articles/generate';
    throw new Error(`Article generation failed: ${err}`);
  }

  const a = res.article;
  const hero = a.heroImage || {};

  // camelCase → snake_case, matching the `articles` collection fields
  // used by the rest of the codebase (see lib/articles.ts).
  // Author arrives as the full object — we keep only the slug so Directus
  // resolves the M2O against the `authors` collection. If the slug doesn't
  // exist yet, the item-create step will 4xx — seed the four canonical
  // authors (baguette, sofia-mendoza, diego-ramirez, ana-vargas) once.
  return {
    payload: {
      slug:                a.slug,
      title:               a.title,
      short:               a.short,
      excerpt:             a.excerpt,
      category:            a.category,
      status:              'draft',
      published_at:        a.publishedAt,
      read_minutes:        a.readMinutes,
      hero_image_alt:      hero.alt || '',
      hero_image_caption:  hero.caption || null,
      body:                a.body || [],
      body_eli5:           a.bodyEli5 || null,
      author:              (a.author && a.author.slug) || 'baguette'
    },
    topic: data.pick_topic && data.pick_topic.topic,
    usage: res.usage || null
  };
};
